package com.huy.enterprise.inventory; import com.huy.enterprise.common.BaseEntity; import com.huy.enterprise.common.enums.RecordStatus; import jakarta.persistence.*; import lombok.*; @Getter @Setter @Entity @Table(name="warehouses") public class Warehouse extends BaseEntity {@Column(name="warehouse_code",nullable=false,unique=true,length=100) private String warehouseCode; @Column(nullable=false) private String name; private String address; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private RecordStatus status=RecordStatus.ACTIVE;}
